Fixes: 9b947a13e7f6 ("regmap: use debugfs even when no device")
Signed-off-by: Xiaolei Wang <xiaolei.wang@windriver.com>
Link: https://lore.kernel.org/r/20201229105046.41984-1-xiaolei.wang@windriver.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug was caused by the unnecessary reallocation of memory for `map->debugfs_name` in the `regmap_debugfs_init` function when it was already allocated. This led to a memory leak because the previously allocated memory was not freed before the new allocation, resulting in unreferenced memory blocks if the function was called multiple times without proper cleanup.

Here is the patch:

 void regmap_debugfs_init(struct regmap *map)
 {
 	struct rb_node *next;
 	struct regmap_range_node *range_node;
 	const char *devname = "dummy";
 	const char *name = map->name;

 	/*
 	 * Userspace can initiate reads from the hardware over debugfs.
 	 * Normally internal regmap structures and buffers are protected with
 	 * a mutex or a spinlock, but if the regmap owner decided to disable
 	 * all locking mechanisms, this is no longer the case. For safety:
 	 * don't create the debugfs entries if locking is disabled.
 	 */
 	if (map->debugfs_disable) {
 		dev_dbg(map->dev, "regmap locking disabled - not creating debugfs entries\n");
 		return;
 	}

 	/* If we don't have the debugfs root yet, postpone init */
 	if (!regmap_debugfs_root) {
 		struct regmap_debugfs_node *node;
 		node = kzalloc(sizeof(*node), GFP_KERNEL);
 		if (!node)
 			return;
 		node->map = map;
 		mutex_lock(&regmap_debugfs_early_lock);
 		list_add(&node->link, &regmap_debugfs_early_list);
 		mutex_unlock(&regmap_debugfs_early_lock);
 		return;
 	}

 	INIT_LIST_HEAD(&map->debugfs_off_cache);
 	mutex_init(&map->cache_lock);

 	if (map->dev)
 		devname = dev_name(map->dev);

 	if (name) {
-		map->debugfs_name = kasprintf(GFP_KERNEL, "%s-%s",
+		if (!map->debugfs_name) {
+			map->debugfs_name = kasprintf(GFP_KERNEL, "%s-%s",
 					      devname, name);
+			if (!map->debugfs_name)
+				return;
+		}
 		name = map->debugfs_name;
 	} else {
 		name = devname;
 	}

 	if (!strcmp(name, "dummy")) {
-		kfree(map->debugfs_name);
+		if (!map->debugfs_name)
+			kfree(map->debugfs_name);

 		map->debugfs_name = kasprintf(GFP_KERNEL, "dummy%d",
 						dummy_index);
+		if (!map->debugfs_name)
+				return;
 		name = map->debugfs_name;
 		dummy_index++;
 	}

 	map->debugfs = debugfs_create_dir(name, regmap_debugfs_root);

 	debugfs_create_file("name", 0400, map->debugfs,
 			    map, &regmap_name_fops);

 	debugfs_create_file("range", 0400, map->debugfs,
 			    map, &regmap_reg_ranges_fops);

 	if (map->max_register || regmap_readable(map, 0)) {
 		umode_t registers_mode;

 #if defined(REGMAP_ALLOW_WRITE_DEBUGFS)
 		registers_mode = 0600;
 #else
 		registers_mode = 0400;
 #endif

 		debugfs_create_file("registers", registers_mode, map->debugfs,
 				    map, &regmap_map_fops);
 		debugfs_create_file("access", 0400, map->debugfs,
 				    map, &regmap_access_fops);
 	}

 	if (map->cache_type) {
 		debugfs_create_file("cache_only", 0600, map->debugfs,
 				    &map->cache_only, &regmap_cache_only_fops);
 		debugfs_create_bool("cache_dirty", 0400, map->debugfs,
 				    &map->cache_dirty);
 		debugfs_create_file("cache_bypass", 0600, map->debugfs,
 				    &map->cache_bypass,
 				    &regmap_cache_bypass_fops);
 	}

 	next = rb_first(&map->range_tree);
 	while (next) {
 		range_node = rb_entry(next, struct regmap_range_node, node);

 		if (range_node->name)
 			debugfs_create_file(range_node->name, 0400,
 					    map->debugfs, range_node,
 					    &regmap_range_fops);

 		next = rb_next(&range_node->node);
 	}

 	if (map->cache_ops && map->cache_ops->debugfs_init)
 		map->cache_ops->debugfs_init(map);
 }



